import * as THREE from "three";

// Ocean setting: a big curling wave behind the surfer, animated open water
// in front, gradient sky, sun, drifting clouds, and distant gulls.

const waterMat = new THREE.MeshStandardMaterial({
  color: 0x12808f, roughness: 0.42, metalness: 0.05,
});
const waveMat = new THREE.MeshStandardMaterial({
  color: 0x0f7d90, roughness: 0.32, metalness: 0.05, side: THREE.DoubleSide,
});
const foamMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });

// Cross-section of the wave in the (z, y) plane: rises from the trough in
// front, steepens, and curls over toward the camera at the lip.
const PROFILE = [
  [2.6, -0.25], [1.4, 0.0], [0.55, 0.55], [0.0, 1.35], [-0.3, 2.4],
  [-0.38, 3.45], [-0.15, 4.35], [0.35, 5.0], [1.0, 5.32], [1.62, 5.22],
  [2.02, 4.82], [2.08, 4.32], [1.78, 3.95], [1.3, 3.82],
];

function createWave() {
  const group = new THREE.Group();
  const curve = new THREE.CatmullRomCurve3(
    PROFILE.map(([z, y]) => new THREE.Vector3(0, y, z)));
  const profilePts = curve.getPoints(56);
  const width = 30, cols = 42, rows = profilePts.length;
  const positions = [];
  const indices = [];
  for (let i = 0; i < cols; i++) {
    const x = -width / 2 + (width * i) / (cols - 1);
    const swell = Math.sin(x * 0.22) * 0.22 - Math.abs(x) * 0.012;
    for (let j = 0; j < rows; j++) {
      const p = profilePts[j];
      const lift = swell * (j / rows);
      positions.push(x, p.y + lift, p.z + Math.sin(x * 0.3 + j * 0.1) * 0.05);
    }
  }
  for (let i = 0; i < cols - 1; i++) {
    for (let j = 0; j < rows - 1; j++) {
      const a = i * rows + j, b = a + rows;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const wave = new THREE.Mesh(geo, waveMat);
  wave.receiveShadow = true;
  group.add(wave);

  // foam clustered along the throwing lip (end of the profile)
  const lip = profilePts[rows - 6];
  const foam = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), foamMat, 110);
  const dummy = new THREE.Object3D();
  const foamSeeds = [];
  for (let i = 0; i < 110; i++) {
    const x = -14 + Math.random() * 28;
    const s = { x, off: (Math.random() - 0.5) * 0.7, drop: Math.random() * 0.55, r: 0.14 + Math.random() * 0.3, ph: Math.random() * 6.28 };
    foamSeeds.push(s);
  }
  group.add(foam);

  // foam streaks at the base of the face
  const baseFoam = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), foamMat, 70);
  for (let i = 0; i < 70; i++) {
    dummy.position.set(-14 + Math.random() * 28, 0.02 + Math.random() * 0.12, 1.5 + Math.random() * 1.1);
    dummy.scale.set(0.5 + Math.random() * 0.9, 0.1 + Math.random() * 0.12, 0.28 + Math.random() * 0.4);
    dummy.rotation.set(0, Math.random() * 3, 0);
    dummy.updateMatrix();
    baseFoam.setMatrixAt(i, dummy.matrix);
  }
  group.add(baseFoam);

  function update(t) {
    group.position.y = Math.sin(t * 0.5) * 0.05;
    for (let i = 0; i < foamSeeds.length; i++) {
      const s = foamSeeds[i];
      const pulse = 1 + Math.sin(t * 2.2 + s.ph) * 0.18;
      dummy.position.set(s.x, lip.y - s.drop + Math.sin(t * 1.4 + s.ph) * 0.05, lip.z + s.off);
      dummy.scale.set(s.r * 1.5 * pulse, s.r * pulse, s.r * pulse);
      dummy.rotation.set(0, s.ph, 0);
      dummy.updateMatrix();
      foam.setMatrixAt(i, dummy.matrix);
    }
    foam.instanceMatrix.needsUpdate = true;
  }
  group.position.set(0, 0, -2.4);
  return { group, update };
}

